window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[12]={"id":"012","numero":12,"titre":"Violences sexuelles","objectifs":[{"id":"12-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition et les différents types de violences sexuelles et du consentement","contenu":"<div class=\"callout callout-info\"><strong>Violence sexuelle.</strong> Tout <span class=\"kw-def\">acte sexuel</span>, tentative d'acte sexuel, commentaire ou avance de nature sexuelle <span class=\"kw-def\">utilisant la coercition</span> (fait de contraindre), commis par une personne <strong>indépendamment de sa relation avec la victime</strong> et dans <strong>tout contexte</strong> (foyer, travail, espace public…).</div>\n\n      <p>Le code pénal distingue les infractions selon le <strong>contact physique</strong> puis la <strong>pénétration</strong> :</p>\n\n      <table >\n        <thead><tr><th>Type</th><th>Définition</th><th>Qualification</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Atteinte sexuelle</span></td>\n            <td>Comportement sexuel <strong>sans</strong> violence, contrainte, <span class=\"kw-alerte\">menace</span> ni surprise (consentement vicié) ; vise surtout le <span class=\"kw-clinique\">majeur sur mineur &lt; 15 ans</span>, même « consentant ».</td>\n            <td><span class=\"kw-alerte\">Délit</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Harcèlement sexuel</span></td>\n            <td>Imposer de façon <strong>répétée</strong> des propos / comportements à connotation sexuelle ou sexiste portant atteinte à la dignité, ou créant une situation intimidante / hostile / offensante.</td>\n            <td><span class=\"kw-alerte\">Délit</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Exhibition sexuelle</span></td>\n            <td>Imposer à la vue d'autrui, dans un lieu accessible au public, une <strong>partie dénudée du corps</strong> ou la commission explicite d'un acte sexuel réel ou simulé.</td>\n            <td><span class=\"kw-alerte\">Délit</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Agression sexuelle</span></td>\n            <td>Atteinte sexuelle commise avec <span class=\"kw-clinique\">violence, contrainte (physique ou morale), menace ou surprise</span> — donc sans consentement clair. <strong>Exclut</strong> la pénétration et les actes bucco-génitaux.</td>\n            <td><span class=\"kw-alerte\">Délit</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Viol</span></td>\n            <td>Tout acte de <span class=\"kw-clinique\">pénétration</span> (vaginale, anale, buccale, par le sexe, les doigts ou un objet) <strong>ou</strong> tout acte bucco-génital, commis par violence, contrainte, <span class=\"kw-alerte\">menace</span> ou surprise — sur la victime <strong>ou</strong> par la victime.</td>\n            <td><span class=\"kw-alerte\">Crime</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> La différence agression / viol = la <span class=\"kw-alerte\">pénétration</span> (vaginale, anale ou buccale). Le <strong>viol est une agression sexuelle</strong> aggravée par la pénétration ⭐ — mais l'inverse est faux : une agression sexuelle n'est pas un viol. Chez le <span class=\"kw-clinique\">mineur &lt; 15 ans</span>, tout comportement sexuel, <strong>même sans violence ni contrainte</strong>, est une violence sexuelle ; le viol entre majeur et mineur &lt;<span class=\"kw-chiffre\"> 15 ans</span> est caractérisé dès une <span class=\"kw-chiffre\">différence d'âge ≥ 5 ans</span>.</div>\n\n      <h4 class=\"kw-def\">Le consentement</h4>\n      <p>Le consentement à une activité sexuelle doit réunir <strong>4 qualités</strong> et peut être <strong>retiré à tout moment</strong> :</p>\n      <ul>\n        <li><strong>Libre</strong> : en dehors de toute <span class=\"kw-clinique\">contrainte physique ou morale</span>.</li>\n        <li><strong>Explicite</strong> : oralement ou par un comportement — un <span class=\"kw-alerte\">silence n'est pas un consentement</span>.</li>\n        <li><strong>Éclairé</strong> : donné par une personne en état de comprendre, dont le jugement n'est pas <span class=\"kw-clinique\">altéré par des substances psychoactives</span>.</li>\n        <li><strong>Mutuel</strong> : donné par l'ensemble des participants.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège mineur.</strong> Le mineur &lt;<span class=\"kw-chiffre\"> 15 ans</span> ne dispose <span class=\"kw-alerte\">pas du discernement nécessaire</span> : son consentement « ne peut être valide ».</div>","frequence":2},{"id":"12-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie des violences sexuelles en France","contenu":"<div class=\"callout callout-info\"><strong>Message clé.</strong> Les violences sexuelles persistent à <strong>tous les âges</strong>, touchent <strong>majoritairement les femmes jeunes</strong>, sont commises le plus souvent par un <span class=\"kw-etio\">proche</span>, et sont <span class=\"kw-alerte\">massivement sous-déclarées</span>.</div>\n      <p><strong>Source de référence :</strong> enquête <span class=\"kw-def\">Virage</span> (Violences et rapports de genre, Ined) — <span class=\"kw-chiffre\">2015</span>, n = <span class=\"kw-chiffre\">27 000</span> personnes de <span class=\"kw-chiffre\">20 – 69 ans</span> en France métropolitaine.</p>\n\n\n      <table >\n        <thead><tr><th>Indicateur</th><th>Femmes</th><th>Hommes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Prévalence des violences sexuelles</span></td>\n            <td><span class=\"kw-chiffre\">15 – 20 %</span> (dont <span class=\"kw-chiffre\">3,3 %</span> de viols)</td>\n            <td><span class=\"kw-chiffre\">3 – 6 %</span> (dont <span class=\"kw-chiffre\">0,5 %</span> de viols)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Survenue avant 18 ans</span></td>\n            <td><span class=\"kw-chiffre\">&gt; 50 %</span> avant la majorité</td>\n            <td><span class=\"kw-chiffre\">2/3</span> avant la majorité</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Victimes, agresseurs et lieux</h4>\n      <ul>\n        <li><strong>Victimes de viols :</strong> majoritairement des <span class=\"kw-clinique\">femmes jeunes de 10 – 24 ans</span> (toutes catégories d'âge et de sexe néanmoins touchées).</li>\n        <li><strong>Agresseurs :</strong> majoritairement des <span class=\"kw-etio\">hommes jeunes</span> ; la plupart des viols sont commis par la catégorie <span class=\"kw-etio\">« famille et proches »</span>, quel que soit le sexe de la victime.</li>\n        <li><strong>Enfance :</strong> <span class=\"kw-chiffre\">1 enfant sur 5</span> est victime de violence sexuelle ; dans <span class=\"kw-chiffre\">80 %</span> des cas la victime <span class=\"kw-etio\">connaît son agresseur</span>.</li>\n        <li><strong>Lieux :</strong> femmes → <span class=\"kw-etio\">tous les espaces de vie</span> (travail, études, couple, famille, espace public) ; agressions par inconnu → plutôt l'<span class=\"kw-etio\">espace public</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Sous-déclaration et disparités des chiffres</h4>\n      <ul>\n        <li><span class=\"kw-chiffre\">10 %</span> seulement des femmes adultes portent plainte, et <span class=\"kw-chiffre\">10 %</span> de ces plaintes aboutissent à une condamnation ; <span class=\"kw-chiffre\">1/3</span> des enfants victimes n'en parlent à personne.</li>\n        <li>Facteurs de sous-estimation : violence <span class=\"kw-clinique\">non reconnue comme telle</span> par la victime, <span class=\"kw-clinique\">amnésie post-traumatique</span>, <span class=\"kw-clinique\">honte, culpabilité, peur</span>.</li>\n        <li>Limites des grandes enquêtes : <span class=\"kw-alerte\">exclusion des mineurs</span> et des <span class=\"kw-alerte\">majeurs &gt; 75 ans</span>.</li>\n      </ul>","frequence":2},{"id":"12-3","rang":"B","rubrique":"Définition","titre":"Connaître les applications médicales de la législation relative aux violences sexuelles","contenu":"<div class=\"callout callout-info\"><strong>Cadre.</strong> Trois <span class=\"kw-def\">niveaux d'infraction</span> selon la gravité, chacun avec son tribunal, ses peines et son délai de prescription. Les peines sont <strong>aggravées</strong> par les circonstances aggravantes.</div>\n\n      <table >\n        <thead><tr><th>Infraction</th><th>Tribunal</th><th>Prison</th><th>Prescription</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Contravention</span><br><em>(ex. outrage sexiste)</em></td>\n            <td>Tribunal de police</td>\n            <td><span class=\"kw-alerte\">Non</span> (amende + stages)</td>\n            <td><span class=\"kw-chiffre\">1 an</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Délit</span><br><em>(agression, harcèlement, exhibition)</em></td>\n            <td>Tribunal correctionnel</td>\n            <td><span class=\"kw-alerte\">Oui</span></td>\n            <td><span class=\"kw-chiffre\">6 ans</span> (majeur)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Crime</span><br><em>(viol)</em></td>\n            <td>Cour d'assises</td>\n            <td><span class=\"kw-alerte\">Oui</span></td>\n            <td><span class=\"kw-chiffre\">20 ans</span> (majeur) à <span class=\"kw-chiffre\">30 ans</span> (mineur)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Délais de prescription (point de départ selon l'âge)</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Mineur &lt;<span class=\"kw-chiffre\"> 15 ans</span></th><th>Mineur <span class=\"kw-chiffre\">15 – 18 ans</span></th><th>Majeur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Atteinte sexuelle</span></td><td><span class=\"kw-chiffre\">10 ans</span> après la majorité</td><td><span class=\"kw-chiffre\">6 ans</span> après la majorité</td><td><span class=\"kw-chiffre\">6 ans</span></td></tr>\n          <tr><td><span class=\"kw-def\">Agression sexuelle</span></td><td><span class=\"kw-chiffre\">20 ans</span> après la majorité</td><td><span class=\"kw-chiffre\">10 ans</span> après la majorité</td><td><span class=\"kw-chiffre\">10 ans</span></td></tr>\n          <tr><td><span class=\"kw-def\">Viol</span></td><td><span class=\"kw-chiffre\">30 ans</span> après la majorité</td><td><span class=\"kw-chiffre\">20 ans</span> après la majorité</td><td><span class=\"kw-chiffre\">20 ans</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Principales peines encourues</h4>\n      <ul>\n        <li><strong>Atteinte sexuelle sur mineur &lt;<span class=\"kw-chiffre\"> 15 ans</span></strong> (loi 2018) : <span class=\"kw-chiffre\">7 ans</span> de prison + <span class=\"kw-chiffre\">100 000 €</span>.</li>\n        <li><strong>Agression sexuelle</strong> : jusqu'à <span class=\"kw-chiffre\">10 ans</span> + <span class=\"kw-chiffre\">100 000 €</span>.</li>\n        <li><strong>Viol</strong> (crime) : <span class=\"kw-chiffre\">15 ans</span> de réclusion ; <span class=\"kw-chiffre\">20 ans</span> si circonstance aggravante ; <span class=\"kw-chiffre\">30 ans</span> s'il entraîne la mort ; <span class=\"kw-alerte\">perpétuité</span> si torture / actes de barbarie.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Circonstances aggravantes (article 222-24)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Mutilation ou infirmité permanente</span> ; victime <span class=\"kw-clinique\">mineure &lt; 15 ans</span> ou <span class=\"kw-clinique\">vulnérable</span> (âge, maladie, infirmité, <span class=\"kw-ci\">grossesse</span>, précarité).</li>\n        <li>Auteur <span class=\"kw-etio\">ascendant / ayant autorité</span> ; <span class=\"kw-etio\">plusieurs auteurs</span> (en réunion) ; auteur <span class=\"kw-etio\">conjoint / ex-conjoint</span>.</li>\n        <li><span class=\"kw-etio\">Usage ou menace d'une arme</span> ; <span class=\"kw-etio\">diffusion numérique</span> ; <span class=\"kw-etio\">mineur présent</span> au moment des faits.</li>\n        <li>Auteur <span class=\"kw-etio\">sous alcool ou stupéfiants</span> ; <span class=\"kw-alerte\">administration d'une substance à la victime</span> pour altérer son discernement.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 13 — Certificats médicaux · 57 — Maltraitance, enfant en danger</em></p>","frequence":0},{"id":"12-4","rang":"A","rubrique":"Définition","titre":"Connaître les particularités des violences sexuelles au sein du couple (violence conjugale)","contenu":"<div class=\"callout callout-info\"><strong>Repères légaux.</strong> Le <span class=\"kw-def\">viol conjugal</span> est reconnu dans la loi française depuis <span class=\"kw-chiffre\">1992</span> ; depuis <span class=\"kw-chiffre\">2006</span>, le fait que l'acte soit commis par le conjoint ou ex-conjoint (qu'ils cohabitent ou non) est un <span class=\"kw-alerte\">facteur aggravant</span> — la présomption de consentement entre époux a été abandonnée.</div>\n\n      <h4 class=\"kw-def\">Formes et fréquence</h4>\n      <ul>\n        <li><strong>Verbale :</strong> insultes à caractère sexuel.</li>\n        <li><strong>Psychologique :</strong> interdiction d'accès à une <span class=\"kw-clinique\">contraception</span>, pratiques sexuelles imposées, humiliation, domination.</li>\n        <li><strong>Physique :</strong> <span class=\"kw-clinique\">rapports sexuels imposés</span>.</li>\n        <li>Dans <span class=\"kw-chiffre\">50 %</span> des cas de violences sexuelles, l'agresseur est le <span class=\"kw-etio\">conjoint ou ex-conjoint</span> ; <span class=\"kw-chiffre\">11 %</span> seulement déposent plainte.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Facteurs favorisants et conséquences</h4>\n      <p><strong>FdR :</strong> <span class=\"kw-etio\">grossesse</span> (≈ <span class=\"kw-chiffre\">40 %</span> des violences débutent pendant la <span class=\"kw-ci\">grossesse</span>) et <span class=\"kw-etio\">séparation</span>. Conséquences obstétricales : <span class=\"kw-clinique\">avortement ×2</span>, <span class=\"kw-clinique\">IST ×1,5</span>, <span class=\"kw-clinique\">fausse couche ×1,9</span>, <span class=\"kw-clinique\">prématurité +23 %</span>.</p>\n\n      <h4 class=\"kw-def\">Cycle des violences conjugales (4 phases, qui se raccourcissent)</h4>\n      <table >\n        <thead><tr><th>Phase</th><th>Agresseur</th><th>Victime</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1 · Tension</strong></td><td>Instaure un <span class=\"kw-clinique\">climat de tension</span></td><td>Tente de faire baisser la tension</td></tr>\n          <tr><td><strong>2 · Explosion</strong></td><td><span class=\"kw-alerte\">Explosion de violence</span> (verbale, psychologique, sexuelle)</td><td>Humiliée, triste, en colère</td></tr>\n          <tr><td><strong>3 · Justification</strong></td><td>Minimise, s'excuse, promet de changer</td><td>Cherche à comprendre, se sent <span class=\"kw-clinique\">responsable</span></td></tr>\n          <tr><td><strong>4 · Lune de miel</strong></td><td>Se montre sous son meilleur jour</td><td>Donne une chance, change ses habitudes</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le <span class=\"kw-alerte\">raccourcissement progressif des phases</span> (parfois sur une seule journée) entretient l'<span class=\"kw-clinique\">emprise</span> et explique la difficulté à quitter l'agresseur.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 13 — Certificats médicaux</em></p>","frequence":1},{"id":"12-5","rang":"B","rubrique":"Définition","titre":"Connaître la définition d’un signalement judiciaire et d’une réquisition judiciaire","contenu":"<div class=\"callout callout-danger\"><strong>À ne pas confondre.</strong> Le <span class=\"kw-def\">signalement</span> est une <strong>démarche d'initiative du médecin</strong> pour protéger une victime (dérogation au secret) ; la <span class=\"kw-def\">réquisition</span> est un <strong>ordre de la justice</strong> (OPJ / magistrat) imposant au médecin de procéder à des constatations ou prélèvements.</div>\n\n      <table >\n        <thead><tr><th>Acte</th><th>Définition</th><th>Qui en est à l'origine ?</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Signalement judiciaire</span></td>\n            <td>Porter à la connaissance des <strong>autorités compétentes</strong> des <span class=\"kw-clinique\">faits graves</span> nécessitant des mesures appropriées, dans le but de <span class=\"kw-clinique\">protéger une victime</span> ou d'empêcher un <span class=\"kw-alerte\">meurtre</span> ou un <span class=\"kw-alerte\">suicide</span>.</td>\n            <td><strong>Le médecin</strong> (démarche spontanée) — constitue une <span class=\"kw-alerte\">dérogation au secret médical</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Réquisition judiciaire</span></td>\n            <td>Document par lequel un <span class=\"kw-clinique\">OPJ</span> (ou magistrat) requiert toute personne qualifiée pour procéder à des constatations / examens.</td>\n            <td><strong>La justice</strong> — ne peut pas servir à obtenir des renseignements médicaux ; les prélèvements sont <span class=\"kw-alerte\">scellés immédiatement par l'OPJ</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Où adresser un signalement d'enfant en danger ?</h4>\n      <ul>\n        <li><strong>Au président du conseil départemental</strong> via la <span class=\"kw-def\">CRIP</span> (cellule de recueil des informations préoccupantes) : <span class=\"kw-clinique\">information préoccupante (IP)</span> ou signalement, pour évaluer la situation du mineur et décider d'éventuelles actions de protection.</li>\n        <li><strong>Au procureur de la République</strong> : signalement, par tout moyen (téléphone puis écrit), <span class=\"kw-chiffre\">joignable 24 h/24</span>, en cas de <span class=\"kw-alerte\">danger plus immédiat</span> pour le <span class=\"kw-clinique\">mineur</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Certificat sur demande spontanée.</strong> Quand la victime demande elle-même un <span class=\"kw-def\">certificat médical initial</span>, le médecin <strong>ne peut pas se soustraire</strong> à cette demande.</div>","frequence":4},{"id":"12-6","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les situations relevant d’un signalement judicaire","contenu":"<div class=\"callout callout-danger\"><strong>Objectif le plus tombé de l'item.</strong> Le <span class=\"kw-def\">secret professionnel</span> (article 226-13) <strong>ne s'applique pas</strong> dans une liste de situations précises. La règle dépend du <strong>statut de la victime</strong> (mineure / majeure) et de son <strong>accord</strong>.</div>\n\n      <h4 class=\"kw-def\">Situations qui relèvent d'un signalement</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Violences physiques, sexuelles ou psychiques</span>.</li>\n        <li><span class=\"kw-alerte\">Constat d'une mutilation sexuelle</span>, ou <span class=\"kw-alerte\">danger imminent de mutilation</span> sexuelle.</li>\n        <li><span class=\"kw-clinique\">Violence conjugale</span>, avec ou sans danger vital immédiat + <span class=\"kw-alerte\">emprise</span>.</li>\n        <li><span class=\"kw-alerte\">Arme</span> (<span class=\"kw-etio\">acquise</span> ou en cours d'acquisition) + danger pour autrui ou soi-même.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Quand le secret est-il levé ? (selon la victime)</h4>\n      <table >\n        <thead><tr><th>Situation de la victime</th><th>Levée du secret ?</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Mineure</span>, ou personne <strong>non en mesure de se protéger</strong> (âge, incapacité physique ou psychique)</td>\n            <td><span class=\"kw-alerte\">Signalement possible sans accord</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Majeure</span> qui <strong>a donné son accord</strong></td>\n            <td><span class=\"kw-alerte\">Signalement possible</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Majeure sans accord</span></td>\n            <td>Possible <strong>uniquement</strong> si <span class=\"kw-alerte\">3 conditions cumulatives</span> (ci-dessous)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Victime majeure sans accord — 3 conditions cumulatives.</strong>\n        <ul>\n          <li>Les violences mettent <span class=\"kw-alerte\">en jeu de manière immédiate la vie</span> de la victime.</li>\n          <li>La victime est <span class=\"kw-alerte\">sous l'emprise</span> de l'auteur (non en mesure de se protéger).</li>\n          <li>Le médecin <strong>s'efforce d'obtenir le consentement</strong> de la victime.</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\"><strong>Mineur = règle absolue.</strong> Tout constat de mutilation sexuelle, ou toute violence sexuelle chez un <span class=\"kw-clinique\">mineur</span> (ou une personne vulnérable), impose le <span class=\"kw-alerte\">signalement, sans condition d'accord</span>.</div>","frequence":5},{"id":"12-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les objectifs de la prise en charge des victimes d’agression sexuelle","contenu":"<div class=\"callout callout-danger\"><strong>Double <span class=\"kw-alerte\">urgence</span>.</strong> L'agression sexuelle est une urgence <span class=\"kw-alerte\">judiciaire</span> ET <span class=\"kw-alerte\">médicale</span>. La prise en charge est <strong>pluridisciplinaire</strong> (médicale, médico-légale, psychologique, sociale, associative).</div>\n\n      <h4 class=\"kw-def\">Trois grands objectifs de l'accueil</h4>\n      <ul>\n        <li><strong>PEC médicale optimale</strong> : examiner avec soin et <span class=\"kw-clinique\">éviter la répétition des examens génitaux</span> (capital chez le mineur, où l'on peut <span class=\"kw-clinique\">filmer</span> l'examen).</li>\n        <li><strong>Recueil médico-légal</strong> : consigner tous les éléments et réaliser les <span class=\"kw-bio\">prélèvements</span> pouvant établir la preuve et identifier l'agresseur.</li>\n        <li><strong>Apprécier les conséquences psychologiques</strong> initiales et prévenir les complications (infectieuses, psychiques).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Vérifier d'abord la notion de plainte.</strong>\n        <ul>\n          <li><strong>Plainte / réquisition</strong> → examen médical + rédaction du certificat, prélèvements scellés.</li>\n          <li><strong>Pas de plainte</strong> → si l'agression date de <span class=\"kw-chiffre\">&lt; 72 h</span>, PEC <span class=\"kw-alerte\">urgente</span> avec prélèvements conservés.</li>\n        </ul>\n      </div>\n\n      <h4 class=\"kw-def\">Les cinq versants de la prise en charge</h4>\n      <table >\n        <thead><tr><th>Versant</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">Urgence</span> médico-chirurgicale</strong></td><td><span class=\"kw-clinique\">Métrorragie</span>, traumatisme, douleur aiguë, <span class=\"kw-alerte\">risque suicidaire</span>, intoxication aiguë.</td></tr>\n          <tr><td><strong>Médical</strong></td><td><span class=\"kw-alerte\">Risque infectieux</span> : bilan IST ± <span class=\"kw-ttt\">trithérapie (TPE)</span> si &lt;<span class=\"kw-chiffre\"> 48 h</span>. <span class=\"kw-alerte\">Risque de grossesse</span> : <span class=\"kw-bio\">β-hCG</span> + contraception d'<span class=\"kw-alerte\">urgence</span> si &lt;<span class=\"kw-chiffre\"> 120 h</span>.</td></tr>\n          <tr><td><strong>Médico-légal</strong></td><td>Information sur le <span class=\"kw-clinique\">dépôt de plainte</span> et les délais de prescription, signalement selon le cas, <span class=\"kw-bio\">prélèvements</span>, rédaction du <span class=\"kw-def\">certificat médical initial</span>.</td></tr>\n          <tr><td><strong>Psychologique</strong></td><td>Proposer un <span class=\"kw-clinique\">accompagnement psychologique</span> ; <span class=\"kw-def\">suivi</span> hospitalier initial puis orientation.</td></tr>\n          <tr><td><strong>Social / associatif</strong></td><td>Évaluer une <span class=\"kw-clinique\">mise à l'abri</span> (hébergement d'<span class=\"kw-alerte\">urgence</span>), arrêt de travail, remise des <strong>coordonnées des associations</strong> locales.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Prélèvements médico-légaux à visée <span class=\"kw-etio\">génétique</span></h4>\n      <ul>\n        <li><strong>Modalités :</strong> le plus tôt possible (idéalement <span class=\"kw-chiffre\">3-5 jours</span>), <span class=\"kw-clinique\">sans toilette préalable</span>, au spéculum <span class=\"kw-clinique\">NON lubrifié</span>, sur <span class=\"kw-bio\">écouvillon coton sec</span>.</li>\n        <li><strong>Sites :</strong> multiples et localisés — vulve, vagin, culs-de-sac, col, face interne des cuisses ; prélèvements <span class=\"kw-clinique\">buccaux et anaux</span> selon le contexte ; vêtements tachés.</li>\n        <li><strong>Recherche de sperme / cellules de l'agresseur :</strong> <span class=\"kw-bio\">SPZ</span> et biologie moléculaire sur ces sites.</li>\n        <li><strong>Recherche d'<span class=\"kw-bio\">ADN</span> de l'agresseur :</strong> <span class=\"kw-bio\">raclement sous les ongles</span> de la victime (si <span class=\"kw-clinique\">agresseur griffé</span>), <span class=\"kw-bio\">écouvillonnage de salive</span> (si <span class=\"kw-clinique\">morsure</span>), poils / cheveux.</li>\n        <li><strong>Scellés :</strong> apposition immédiate par l'<span class=\"kw-clinique\">OPJ</span>, en <span class=\"kw-alerte\">double exemplaire</span> (contre-expertise) ; numérotés, localisés, à l'abri de la lumière, congelés à <span class=\"kw-chiffre\">-20 °C</span> si non utilisés sous <span class=\"kw-chiffre\">3 jours</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong>Piège classique.</strong> L'<span class=\"kw-alerte\">absence de sperme n'élimine pas une pénétration</span> : elle peut s'expliquer par un <span class=\"kw-clinique\">délai trop important</span>, une <span class=\"kw-clinique\">toilette intime</span>, l'absence de pénétration / d'éjaculation (ou une éjaculation ailleurs), une <span class=\"kw-clinique\">éjaculation rétrograde</span>, le port d'un <span class=\"kw-ttt\">préservatif</span> ou une <span class=\"kw-clinique\">azoospermie</span>.</div>\n\n      <div class=\"callout callout-danger\"><strong>Certificat médical initial (CMI) — règles strictes.</strong> Systématique, remis à la victime (si pas de réquisition) ou à l'autorité requérante. Il <span class=\"kw-alerte\">ne contient aucune accusation ni le nom de l'auteur</span> et ne doit <span class=\"kw-alerte\">jamais employer le mot « viol »</span> (terme juridique réservé à la Justice).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — Infections à <span class=\"kw-etio\">VIH</span> · 167 — Hépatites virales · 36 — Contraception</em></p>","frequence":5},{"id":"12-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les étapes de l’interrogatoire et de l’examen clinique","contenu":"<div class=\"callout callout-warn\"><strong>Règle d'or.</strong> Un <span class=\"kw-alerte\">examen normal n'exclut pas une agression</span>. Chaque étape est expliquée à la victime et fait l'objet d'un <strong>recueil de consentement oral</strong> ; lésions décrites de façon <strong>précise et minutieuse</strong>.</div>\n\n      <h4 class=\"kw-def\">Conditions de l'examen</h4>\n      <ul>\n        <li>Lieu calme, entretien <span class=\"kw-clinique\">empathique, non intrusif, non culpabilisant</span> ; si possible en binôme médecin / IDE ou médecin / sage-femme.</li>\n        <li>De préférence dans un CH équipé : <strong>cellule d'accueil des victimes d'agression sexuelle</strong>, obligatoire dans les CHU <span class=\"kw-chiffre\">24 h/24</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Interrogatoire (anamnèse)</h4>\n      <table >\n        <thead><tr><th>Item</th><th>À préciser</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Circonstances</strong></td><td>Date et heure, nombre d'agresseurs, prise de <span class=\"kw-etio\">toxique</span> / <span class=\"kw-clinique\">soumission chimique</span>.</td></tr>\n          <tr><td><strong>Violences associées</strong></td><td>Type et localisation des coups, menaces / arme, comportement de défense (<span class=\"kw-clinique\">griffures de l'agresseur</span>).</td></tr>\n          <tr><td><strong>Violences sexuelles</strong></td><td><span class=\"kw-clinique\">Pénétration</span> (type, localisation), port d'un <span class=\"kw-ttt\">préservatif</span>, <span class=\"kw-clinique\">éjaculation</span> et sa localisation.</td></tr>\n          <tr><td><strong>Comportement depuis</strong></td><td><span class=\"kw-clinique\">Douche</span>, exonération anale / miction, changement de vêtements, traitement ou substances pris.</td></tr>\n          <tr><td><strong>ATCD</strong></td><td>Vulnérabilité, médico-chirurgicaux, psychiatriques, <span class=\"kw-bio\">GOB</span> (DDR, derniers rapports, grossesses, contraception), <span class=\"kw-ttt\">vaccinations</span>.</td></tr>\n          <tr><td><strong>Symptômes / retentissement</strong></td><td>Troubles génito-anaux, douleurs, signes de soumission chimique, retentissement psychique et <span class=\"kw-alerte\">risque suicidaire</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Examen clinique</h4>\n      <ul>\n        <li><strong>Vêtements et sous-vêtements</strong> (capital) : recherche de <span class=\"kw-clinique\">taches, déchirures</span>.</li>\n        <li><strong>Lésions traumatiques</strong> par zone : <span class=\"kw-clinique\">défense</span> (avant-bras, mains), <span class=\"kw-clinique\">préhension</span> (poignets, épaules, face interne des bras), <span class=\"kw-clinique\">écartement</span> (face interne des cuisses), <span class=\"kw-clinique\">connotation sexuelle</span> (bouche, seins, pubis, vulve, fesses).</li>\n        <li><strong>Examen gynécologique</strong> (toujours avec accord) : inspection vulve / fourchette / clitoris, <span class=\"kw-clinique\">examen de l'hymen</span> — <span class=\"kw-def\">traction divergente des grandes lèvres</span> et, si besoin, <span class=\"kw-def\">sonde de Foley à ballonnet</span> pour préciser une <span class=\"kw-clinique\">rupture complète vs incomplète</span> et estimer la taille de l'orifice hyménéal ; <span class=\"kw-clinique\">spéculum</span> (ou spéculum de vierge si absence de rapport antérieur), ± toucher vaginal.</li>\n        <li><strong>Examen anal</strong> : inspection de la marge et des plis radiés ; anuscopie ± rectoscopie si doute de pénétration ; TR (douleur, tonicité du sphincter).</li>\n        <li><strong>Examen buccal</strong> : contusion du <span class=\"kw-clinique\">frein de la langue</span>, lésions des muqueuses.</li>\n        <li><strong>Soumission chimique</strong> : signes cutanés, plaies d'injection, anomalie du <span class=\"kw-clinique\">diamètre pupillaire</span>, examen neurologique.</li>\n      </ul>","frequence":4},{"id":"12-9","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les situations médicales à risque associées aux violences sexuelles","contenu":"<div class=\"callout callout-danger\"><strong>Quatre risques médicaux à dépister systématiquement :</strong> <span class=\"kw-alerte\">grossesse</span>, <span class=\"kw-alerte\">IST</span>, <span class=\"kw-alerte\">retentissement psychologique</span> et <span class=\"kw-alerte\">situation sociale</span> à risque.</div>\n\n      <ul>\n        <li><strong>Risque de <span class=\"kw-ci\">grossesse</span> :</strong> toute pénétration vaginale ou éjaculation au niveau de la vulve, sans <span class=\"kw-ci\">contraception efficace</span> → <span class=\"kw-bio\">β-hCG</span> et contraception d'<span class=\"kw-alerte\">urgence</span>.</li>\n        <li><strong>Risque <span class=\"kw-etio\">infectieux</span> (IST) :</strong> <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span>, <span class=\"kw-etio\">syphilis</span>, <span class=\"kw-etio\">Chlamydia</span>, <span class=\"kw-etio\">gonocoque</span> → <span class=\"kw-bio\">sérologies</span>, prélèvements locaux ± <span class=\"kw-ttt\">TPE</span>.</li>\n        <li><strong>Risque psychologique :</strong> vérifier l'absence de <span class=\"kw-alerte\">risque suicidaire à court terme</span> ; état de stress aigu / post-traumatique.</li>\n        <li><strong>Risque social :</strong> évaluer la nécessité d'une <span class=\"kw-clinique\">mise à l'abri</span> (danger persistant, emprise).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Soumission chimique.</strong> À évoquer si la victime allègue avoir <span class=\"kw-clinique\">dormi anormalement</span>, présente un <span class=\"kw-clinique\">« trou noir »</span> ou l'impression qu'« il s'est passé quelque chose » sans s'en souvenir → prélèvements toxicologiques urgents (fenêtre étroite).</div>","frequence":1},{"id":"12-10","rang":"B","rubrique":"Diagnostic positif","titre":"Identifier les lésions associées tégumentaires et psychiques","contenu":"<div class=\"callout callout-warn\"><strong>Interprétation prudente.</strong> Les lésions sont souvent <span class=\"kw-alerte\">absentes ou non spécifiques</span> ; un <span class=\"kw-alerte\">érythème vulvaire</span> peut résulter d'une agression, mais aussi d'une vulvite, d'une vulvo-vaginite ou d'un <span class=\"kw-clinique\">prurit</span> (fréquent chez la petite fille).</div>\n\n      <h4 class=\"kw-def\">Lésions tégumentaires : zones évocatrices</h4>\n      <ul>\n        <li><strong>Défense :</strong> bord interne des avant-bras, mains.</li>\n        <li><strong>Préhension :</strong> poignets, épaules, face interne des bras (<span class=\"kw-clinique\">ecchymoses</span>).</li>\n        <li><strong>Chutes :</strong> coudes, genoux, zones saillantes.</li>\n        <li><strong>Connotation sexuelle :</strong> bouche, seins, pubis, vulve, fesses, anus.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Lésions physiologiques <span class=\"kw-bio\">vs</span> suspectes</h4>\n      <table >\n        <thead><tr><th>Site</th><th>Physiologique / non suspect</th><th>Suspect</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Hymen</span></td>\n            <td><span class=\"kw-clinique\">Encoche incomplète</span> ; formes normales (semi-lunaire, annulaire, cribriforme…) ; défloration ancienne cicatrisée non <span class=\"kw-etio\">hémorragique</span> ; <span class=\"kw-clinique\">caroncules myrtiformes</span>.</td>\n            <td><span class=\"kw-alerte\">Encoche complète</span> atteignant le bord d'insertion vaginal ; déchirure ± <span class=\"kw-etio\">hémorragique</span> (souvent à <span class=\"kw-chiffre\">5 h ou 7 h</span>) ; <span class=\"kw-clinique\">érosion</span>, ecchymose.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Anus</span></td>\n            <td>Cicatrices anciennes ; <span class=\"kw-clinique\">hémorroïdes, marisques</span> ; modification du tonus ; disparition des plis radiés <em>(distracteur classique)</em>.</td>\n            <td><span class=\"kw-alerte\">Ecchymoses, hématomes</span> de la marge, érosions, fissures, douleur au TR.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Lésions psychiques.</strong> Retentissement majeur : <span class=\"kw-clinique\">état de stress post-traumatique</span>, <span class=\"kw-clinique\">anxiété</span>, <span class=\"kw-clinique\">dépression</span>, <span class=\"kw-clinique\">troubles du sommeil</span>. Évaluer en priorité le <span class=\"kw-alerte\">risque suicidaire à court terme</span> ; l'évaluation psychique fine est différée (jours / semaines).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble dépressif, anxieux, adaptatif, TSPT, TOC</em></p>","frequence":2},{"id":"12-11","rang":"B","rubrique":"Diagnostic positif","titre":"Identifier une mutilations sexuelle féminine ou masculine","contenu":"<div class=\"callout callout-info\"><strong>Définition (OMS).</strong> Les <span class=\"kw-def\">mutilations sexuelles féminines (MSF)</span> = atteinte ou ablation partielle / totale des organes génitaux externes à des fins <strong>non thérapeutiques</strong>. En France, ≈ <span class=\"kw-chiffre\">125 000 femmes</span> concernées — y penser devant toute anomalie génitale.</div>\n\n      <h4 class=\"kw-def\"><span class=\"kw-def\">Classification</span> OMS</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Type 1</span></td><td>Ablation partielle / totale du <span class=\"kw-clinique\">clitoris et/ou du prépuce</span> (clitoridectomie).</td></tr>\n          <tr><td><span class=\"kw-def\">Type 2</span></td><td>Ablation du clitoris <strong>et des petites lèvres</strong>, ± excision des grandes lèvres.</td></tr>\n          <tr><td><span class=\"kw-def\">Type 3</span></td><td><span class=\"kw-alerte\">Infibulation</span> : rétrécissement de l'orifice vaginal par accolement des petites et/ou grandes lèvres, ± excision du clitoris.</td></tr>\n          <tr><td><span class=\"kw-def\">Type 4</span></td><td>Toute autre intervention sur les OGE à but non thérapeutique (<span class=\"kw-ttt\">ponction</span>, percement, incision, scarification, cautérisation).</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Conduite à tenir</h4>\n      <ul>\n        <li><strong>Complications :</strong> infections, <span class=\"kw-clinique\">douleurs</span> et hémorragies aiguës ; <span class=\"kw-clinique\">dyspareunie</span>, vaginisme, surrisque obstétrical ; <span class=\"kw-clinique\">stress post-traumatique</span>, dépression.</li>\n        <li><strong>PEC :</strong> psychologique / sexologique ; <span class=\"kw-clinique\">reconstruction clitoridienne</span> (prise en charge Sécu) ; <span class=\"kw-clinique\">certificat de non-excision</span> en cas de voyage dans le pays d'origine.</li>\n        <li><span class=\"kw-alerte\">Tout constat de MSF chez une mineure impose un signalement.</span></li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Mutilations sexuelles masculines.</strong> La <span class=\"kw-clinique\">circoncision</span> reste controversée ; la <strong>seule indication médicale justifiable</strong> est le <span class=\"kw-clinique\">phimosis</span> ou le <span class=\"kw-clinique\">paraphimosis</span>.</div>","frequence":1},{"id":"12-12","rang":"B","rubrique":"Prise en charge","titre":"Savoir qu’il existe un traitement d’urgence adapté à la situation","contenu":"<div class=\"callout callout-danger\"><strong>Trois urgences thérapeutiques.</strong> Contraception d'<span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ci\">grossesse</span>), <span class=\"kw-ttt\">TPE</span> (<span class=\"kw-etio\">VIH</span>) et sérovaccination (VHB) — toutes <strong>chrono-dépendantes</strong>.</div>\n\n      <h4 class=\"kw-def\">Contraception d'<span class=\"kw-alerte\">urgence</span></h4>\n      <table >\n        <thead><tr><th>Option</th><th>Délai</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Lévonorgestrel</span> PO (DU <span class=\"kw-chiffre\">1,5 mg</span>)</td>\n            <td>jusqu'à <span class=\"kw-chiffre\">72 h</span></td>\n            <td>Vente libre, gratuit pour mineures et majeures ; d'autant plus efficace que pris tôt ; <strong>aucune CI</strong>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Ulipristal acétate</span> PO (DU <span class=\"kw-chiffre\">30 mg</span>)</td>\n            <td>jusqu'à <span class=\"kw-chiffre\">120 h</span></td>\n            <td>Plus efficace ; <span class=\"kw-ci\">CI : asthme sévère, insuffisance hépatique</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">DIU au cuivre</span></td>\n            <td>jusqu'à <span class=\"kw-chiffre\">120 h</span></td>\n            <td>Méthode la <strong>plus efficace</strong> (1ʳᵉ intention théorique) + contraception prolongée ; plus rarement mise en œuvre.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Prévention infectieuse</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">TPE</span> (traitement post-exposition <span class=\"kw-etio\">VIH</span>) : à débuter jusqu'à <span class=\"kw-chiffre\">48 h</span> des faits, selon le type de rapport et le statut sérologique de l'agresseur (<span class=\"kw-ci\">bilan pré-thérapeutique</span> : <span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">bilan hépatique</span>).</li>\n        <li><span class=\"kw-ttt\">Sérovaccination anti-VHB</span> selon les statuts vaccinal de la victime et sérologique de l'agresseur.</li>\n        <li><span class=\"kw-alerte\">Pas de traitement préventif systématique des IST</span> hors <span class=\"kw-etio\">VIH</span> et VHB (<span class=\"kw-ttt\">antibiothérapie</span> présomptive ± selon contexte) ; rapports protégés conseillés en cas de risque.</li>\n        <li><span class=\"kw-ttt\">Antalgiques</span> et <span class=\"kw-ttt\">anxiolytiques</span> si nécessaire.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception · 169 — Infections à <span class=\"kw-etio\">VIH</span> · 167 — Hépatites virales</em></p>","frequence":1}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://arretonslesviolences.gouv.fr/associations-de-lutte-contre-les-violences-sexistes-et-sexuelles","label":"arretonslesviolences.gouv.fr — annuaire des associations d'aide aux victimes"}],"cards":[{"i":"2eb7eec6a7ee","n":12,"o":"12-1","u":"Définition","t":"Connaître la définition et les différents types de violences sexuelles et du consentement","q":"Quelles sont les quatre qualités que doit réunir le consentement à une activité sexuelle ?","a":"<ul><li><strong>Libre</strong> : en dehors de toute contrainte physique ou morale.</li><li><strong>Explicite</strong> : oralement ou par un comportement ; un silence n'est pas un consentement.</li><li><strong>Éclairé</strong> : donné par une personne en état de comprendre, dont le jugement n'est pas altéré (par des substances psychoactives par exemple).</li><li><strong>Mutuel</strong> : donné par l'ensemble des participants.</li></ul><p>Le consentement peut être retiré à tout moment.</p>"},{"i":"81d5217d04c4","n":12,"o":"12-1","u":"Définition","t":"Connaître la définition et les différents types de violences sexuelles et du consentement","q":"Quelle est la définition générale d'une violence sexuelle ?","a":"<p>Une violence sexuelle est <strong>tout acte sexuel, tentative d'acte sexuel, commentaire ou avance de nature sexuelle</strong> utilisant la <strong>coercition</strong> (fait de contraindre), commis par une personne indépendamment de sa relation avec la victime et dans tout contexte (foyer, travail, espace public).</p>"},{"i":"df6ca78a9c7f","n":12,"o":"12-1","u":"Définition","t":"Connaître la définition et les différents types de violences sexuelles et du consentement","q":"Qu'est-ce que le viol et quelle est la différence clé avec l'agression sexuelle ?","a":"<p>Le <strong>viol</strong> est <strong>tout acte de pénétration</strong> (vaginale, anale, buccale, par le sexe, les doigts ou un objet) ou tout acte bucco-génital, commis par violence, contrainte, menace ou surprise. C'est un <strong>crime</strong>.</p><p>La différence clé avec l'agression sexuelle est la <strong>pénétration</strong>. Le viol est une agression sexuelle aggravée par la pénétration, mais l'inverse est faux : une agression sexuelle n'est pas un viol.</p>"},{"i":"fcd6d1754bde","n":12,"o":"12-1","u":"Définition","t":"Connaître la définition et les différents types de violences sexuelles et du consentement","q":"Quelles sont les qualifications juridiques distinctes des violences sexuelles selon le code pénal français, excluant la pénétration ?","a":"<ul><li>L'<strong>atteinte sexuelle</strong> : comportement sexuel sans violence, contrainte, menace ni surprise, visant le majeur sur mineur de moins de 15 ans, même « consentant ». C'est un <strong>délit</strong>.</li><li>Le <strong>harcèlement sexuel</strong> : imposer de façon répétée des propos ou comportements à connotation sexuelle ou sexiste portant atteinte à la dignité, ou créant une situation intimidante, hostile ou offensante. C'est un <strong>délit</strong>.</li><li>L'<strong>exhibition sexuelle</strong> : imposer à la vue d'autrui, dans un lieu accessible au public, une partie dénudée du corps ou un acte sexuel explicite (réel ou simulé). C'est un <strong>délit</strong>.</li><li>L'<strong>agression sexuelle</strong> : atteinte sexuelle commise avec violence, contrainte, menace ou surprise, excluant la pénétration et les actes bucco-génitaux. C'est un <strong>délit</strong>.</li></ul>"},{"i":"150cbd0b2843","n":12,"o":"12-4","u":"Définition","t":"Connaître les particularités des violences sexuelles au sein du couple (violence conjugale)","q":"Quels sont les principaux facteurs de risque et les conséquences obstétricales des violences sexuelles au sein du couple ?","a":"<ul><li><strong>Facteurs de risque</strong> : la <strong>grossesse</strong> (environ 40 % des violences débutent pendant cette période) et la <strong>séparation</strong>.</li><li><strong>Conséquences obstétricales</strong> : risque d'avortement multiplié par <strong>2</strong>, IST multiplié par <strong>1,5</strong>, fausse couche multiplié par <strong>1,9</strong>, et augmentation de <strong>+23 %</strong> du risque de prématurité.</li></ul>"},{"i":"98ec164c8516","n":12,"o":"12-4","u":"Définition","t":"Connaître les particularités des violences sexuelles au sein du couple (violence conjugale)","q":"Depuis quand le viol conjugal est-il reconnu dans la loi française, et quelle est la position actuelle concernant l'agresseur ?","a":"<p>Le viol conjugal est reconnu dans la loi française depuis <strong>1992</strong>. Depuis <strong>2006</strong>, le fait que l'acte soit commis par le conjoint ou ex-conjoint (qu'ils cohabitent ou non) est un <strong>facteur aggravant</strong>, la présomption de consentement entre époux ayant été abandonnée.</p>"},{"i":"a6606ad48d04","n":12,"o":"12-4","u":"Définition","t":"Connaître les particularités des violences sexuelles au sein du couple (violence conjugale)","q":"Pourquoi le raccourcissement du cycle des violences conjugales est-il un élément important à comprendre face à l'emprise ?","a":"<p>Le raccourcissement progressif des phases (parfois sur une seule journée) entretient l'<strong>emprise</strong> de l'agresseur sur la victime et explique la difficulté pour cette dernière à le quitter.</p>"},{"i":"b66ee68257c3","n":12,"o":"12-4","u":"Définition","t":"Connaître les particularités des violences sexuelles au sein du couple (violence conjugale)","q":"Quelles sont les différentes formes que peuvent prendre les violences sexuelles au sein du couple ?","a":"<ul><li><strong>Verbale</strong> : insultes à caractère sexuel.</li><li><strong>Psychologique</strong> : interdiction d'accès à une contraception, pratiques sexuelles imposées, humiliation, domination.</li><li><strong>Physique</strong> : rapports sexuels imposés.</li></ul>"},{"i":"d3a7cb8963a3","n":12,"o":"12-4","u":"Définition","t":"Connaître les particularités des violences sexuelles au sein du couple (violence conjugale)","q":"Décrivez le cycle des violences conjugales.","a":"<p>Il se compose de 4 phases qui ont tendance à se raccourcir progressivement :</p><ul><li><strong>Phase 1 (Tension)</strong> : l'agresseur instaure un climat de tension, la victime tente de l'apaiser.</li><li><strong>Phase 2 (Explosion)</strong> : explosion de violence (verbale, psychologique, sexuelle) de la part de l'agresseur, la victime est humiliée, triste, en colère.</li><li><strong>Phase 3 (Justification)</strong> : l'agresseur minimise, s'excuse, promet de changer, la victime cherche à comprendre et se sent responsable.</li><li><strong>Phase 4 (Lune de miel)</strong> : l'agresseur se montre sous son meilleur jour, la victime lui donne une chance et change certaines de ses habitudes.</li></ul>"},{"i":"0d4a73d74c59","n":12,"o":"12-6","u":"Identifier une urgence","t":"Identifier les situations relevant d’un signalement judicaire","q":"Dans le cadre de l'identification des situations relevant d’un signalement judiciaire pour violences sexuelles, quelles sont les situations générales qui justifient un signalement ?","a":"Les situations générales qui justifient un signalement incluent les <ul><li><strong>Violences physiques, sexuelles ou psychiques</strong>.</li><li>Le <strong>constat ou le danger imminent de mutilation sexuelle</strong>.</li><li>Les violences conjugales, qu'il y ait ou non un danger vital immédiat, associées à une situation d'<strong>emprise</strong>.</li><li>La présence d'une <strong>arme</strong> (acquise ou en cours d'acquisition) qui représente un danger pour autrui ou soi-même.</li></ul>"},{"i":"8ea30d534fea","n":12,"o":"12-6","u":"Identifier une urgence","t":"Identifier les situations relevant d’un signalement judicaire","q":"Concernant les violences sexuelles, quelle est la règle de levée du secret professionnel et de signalement judiciaire pour une victime <strong>mineure</strong> ou une personne <strong>non en mesure de se protéger</strong> ?","a":"Pour une victime <strong>mineure</strong>, ou une personne non en mesure de se protéger (en raison de l'âge ou d'une incapacité physique ou psychique), le <strong>signalement est possible sans son accord</strong>. Tout constat de mutilation sexuelle ou de violence sexuelle chez un mineur (ou une personne vulnérable) impose le signalement, <strong>sans condition d'accord</strong>."},{"i":"d1aac2abe573","n":12,"o":"12-6","u":"Identifier une urgence","t":"Identifier les situations relevant d’un signalement judicaire","q":"Dans le cas de violences sexuelles sur une victime <strong>majeure sans son accord</strong>, quelles sont les <strong>trois conditions cumulatives</strong> qui permettent une levée du secret professionnel et un signalement judiciaire ?","a":"Pour une victime majeure sans son accord, le signalement est possible uniquement si <strong>trois conditions cumulatives</strong> sont réunies :\n<ul><li>Les violences mettent en jeu de manière <strong>immédiate la vie</strong> de la victime.</li><li>La victime est sous l'<strong>emprise de l'auteur</strong>, la rendant non en mesure de se protéger.</li><li>Le médecin s'est <strong>efforcé d'obtenir le consentement</strong> de la victime.</li></ul>"},{"i":"10a80077b92f","n":12,"o":"12-8","u":"Diagnostic positif","t":"Connaître les étapes de l’interrogatoire et de l’examen clinique","q":"Quels sont les principes fondamentaux à respecter lors de l'examen clinique d'une victime de violences sexuelles ?","a":"<p>L'examen doit toujours être réalisé après explication et recueil d'un <strong>consentement oral</strong> pour chaque étape. Les lésions observées sont décrites avec <strong>précision et minutie</strong>. Il est essentiel que l'examen soit mené dans un <strong>lieu calme</strong>, avec un <strong>entretien empathique, non intrusif et non culpabilisant</strong>, idéalement en binôme médecin/IDE ou médecin/sage-femme et de préférence dans une <strong>cellule d'accueil des victimes d'agression sexuelle</strong> de CH, si possible 24h/24.</p>"},{"i":"266945624568","n":12,"o":"12-8","u":"Diagnostic positif","t":"Connaître les étapes de l’interrogatoire et de l’examen clinique","q":"Quels renseignements essentiels doivent être recueillis lors de l'interrogatoire (anamnèse) d'une victime de violences sexuelles ?","a":"<ul><li><strong>Circonstances</strong>: Date et heure de l'agression, nombre d'agresseurs, éventuelle prise de toxiques ou éléments suggérant une soumission chimique.</li><li><strong>Violences associées</strong>: Type et localisation des coups, menaces (arme), comportements de défense (griffures de l'agresseur).</li><li><strong>Violences sexuelles</strong>: Type et localisation de la pénétration, port d'un préservatif par l'agresseur, éjaculation et sa localisation.</li><li><strong>Comportement de la victime depuis l'agression</strong>: Douche, exonération anale/miction, changement de vêtements, prise de traitements/substances.</li><li><strong>Antécédents médicaux</strong>: Vulnérabilité (médico-chirurgicaux, psychiatriques), gynéco-obstétricaux (DDR, derniers rapports sexuels, grossesses, contraception), statut vaccinal.</li><li><strong>Symptômes et retentissement</strong>: Troubles génito-anaux, douleurs, signes de soumission chimique, retentissement psychique et risque suicidaire.</li></ul>"},{"i":"cb15b2f4cc6d","n":12,"o":"12-8","u":"Diagnostic positif","t":"Connaître les étapes de l’interrogatoire et de l’examen clinique","q":"Quelles sont les cibles prioritaires de l'examen clinique d'une victime de violences sexuelles et quels sont les signes à rechercher ?","a":"<ul><li><strong>Vêtements et sous-vêtements</strong>: Recherche de taches ou déchirures (à capitaliser).</li><li><strong>Lésions traumatiques générales</strong>: Lésions de défense (avant-bras, mains), de préhension (poignets, épaules, face interne des bras), d'écartement (face interne des cuisses), ou à connotation sexuelle (bouche, seins, pubis, vulve, fesses).</li><li><strong>Examen gynécologique</strong> (avec accord): Inspection de la vulve, fourchette vulvaire, clitoris, hymen. Utilisation d'un spéculum (ou <strong>spéculum de vierge</strong> si absence de rapport antérieur) et éventuellement toucher vaginal.</li><li><strong>Examen anal</strong>: Inspection de la marge anale et des plis radiés. Anuscopie ou rectoscopie si suspicion de pénétration. Toucher rectal pour évaluer douleur et tonicité sphinctérienne.</li><li><strong>Examen buccal</strong>: Recherche de contusions du frein de la langue ou de lésions des muqueuses.</li><li><strong>Signes de soumission chimique</strong>: Recherche de signes cutanés, plaies d'injection, anomalies du diamètre pupillaire, évaluation neurologique.</li></ul>"},{"i":"485ed3bde4d5","n":12,"o":"12-9","u":"Identifier une urgence","t":"Identifier les situations médicales à risque associées aux violences sexuelles","q":"Comment évalue-t-on et prend-on en charge le risque de grossesse après des violences sexuelles ?","a":"<p>Le risque de grossesse est présent en cas de <strong>pénétration vaginale</strong> ou d'<strong>éjaculation à la vulve</strong> sans contraception efficace. La prise en charge implique un dosage de la <strong>β-hCG</strong> et la proposition d'une <strong>contraception d'urgence</strong>.</p>"},{"i":"4dff858ac72c","n":12,"o":"12-9","u":"Identifier une urgence","t":"Identifier les situations médicales à risque associées aux violences sexuelles","q":"Quelles sont les IST à dépister et les modalités de leur dépistage après des violences sexuelles ?","a":"<p>Les IST à dépister sont le <strong>VIH</strong>, le <strong>VHB</strong>, le <strong>VHC</strong>, la <strong>syphilis</strong>, la <strong>Chlamydia</strong> et le <strong>gonocoque</strong>. Le dépistage s'effectue par des <strong>sérologies</strong> et des <strong>prélèvements locaux</strong>. Une éventuelle <strong>TPE (traitement post-exposition)</strong> est à discuter.</p>"},{"i":"7d2fb7e0ce53","n":12,"o":"12-9","u":"Identifier une urgence","t":"Identifier les situations médicales à risque associées aux violences sexuelles","q":"Quand faut-il évoquer une soumission chimique suite à des violences sexuelles et quelle est la conduite à tenir ?","a":"<p>Une soumission chimique doit être évoquée si la victime allègue avoir <strong>dormi anormalement</strong>, présente un <strong>« trou noir »</strong> ou l'impression qu'« il s'est passé quelque chose » sans s'en souvenir. La conduite à tenir est de réaliser des <strong>prélèvements toxicologiques en urgence</strong>, compte tenu d'une fenêtre de détection étroite.</p>"},{"i":"e083cf388291","n":12,"o":"12-9","u":"Identifier une urgence","t":"Identifier les situations médicales à risque associées aux violences sexuelles","q":"Quels sont les quatre principaux risques médicaux qu'il faut dépister systématiquement suite à des violences sexuelles ?","a":"<p>Les quatre risques médicaux à dépister systématiquement après des violences sexuelles sont :</p><ul><li>La <strong>grossesse</strong>.</li><li>Les <strong>Infections Sexuellement Transmissibles (IST)</strong>.</li><li>Le <strong>retentissement psychologique</strong>.</li><li>La <strong>situation sociale à risque</strong>.</li></ul>"}]};